{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test test/*.test.js"
  }
}
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { openWorkboardStore } from './store.js';
import { notFoundPage, projectPage, projectsPage } from './views.js';

const styles = readFileSync(new URL('../public/styles.css', import.meta.url), 'utf8');
const browserScript = readFileSync(new URL('../public/app.js', import.meta.url), 'utf8');

function taskFilter(value) {
  return ['All', 'Open', 'Completed'].includes(value) ? value : 'All';
}

function taskPriorityFilter(value) {
  return ['All', 'Low', 'Normal', 'High'].includes(value) ? value : 'All';
}

function projectLocation(id, filter, priorityFilter) {
  const query = new URLSearchParams({ filter });
  if (priorityFilter !== 'All') query.set('priorityFilter', priorityFilter);
  return `/projects/${id}?${query}`;
}

function projectFilter(value) {
  return value === 'Archived' ? 'Archived' : 'Active';
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

function send(response, status, body, contentType = 'text/html; charset=utf-8') {
  response.writeHead(status, { 'Content-Type': contentType });
  response.end(body);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 16384) {
      const error = new Error('Form is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

export function createWorkboardServer(databasePath) {
  const store = openWorkboardStore(databasePath);
  const server = createServer(async (request, response) => {
    try {
      const { pathname, searchParams } = new URL(request.url, 'http://localhost');
      if (request.method === 'GET' && pathname === '/health') {
        send(response, 200, JSON.stringify({ status: 'ok' }), 'application/json');
      } else if (request.method === 'GET' && pathname === '/styles.css') {
        send(response, 200, styles, 'text/css; charset=utf-8');
      } else if (request.method === 'GET' && pathname === '/app.js') {
        send(response, 200, browserScript, 'text/javascript; charset=utf-8');
      } else if (request.method === 'GET' && pathname === '/') {
        const filter = projectFilter(searchParams.get('filter'));
        send(response, 200, projectsPage(store.list(filter), '', '', filter));
      } else if (request.method === 'POST' && pathname === '/projects') {
        const form = await readForm(request);
        const name = form.get('name') ?? '';
        const project = store.create(name);
        if (project.error) {
          send(response, 400, projectsPage(store.list(), project.error, name));
        } else {
          redirect(response, '/');
        }
      } else if (/^\/projects\/[1-9]\d*(?:\/(?:archive|restore|rename|default-task-priority|tasks(?:\/[1-9]\d*\/(?:completion|rename|priority|due-date))?))?$/.test(pathname)) {
        const parts = pathname.split('/');
        const id = Number(parts[2]);
        const project = Number.isSafeInteger(id) ? store.find(id) : undefined;
        if (!project) {
          send(response, 404, notFoundPage());
        } else if (request.method === 'GET' && parts.length === 3) {
          const filter = taskFilter(searchParams.get('filter'));
          const priorityFilter = taskPriorityFilter(searchParams.get('priorityFilter'));
          send(response, 200, projectPage(project, store.tasks.list(id, filter, priorityFilter), { filter, priorityFilter }));
        } else if (request.method === 'POST' && ['archive', 'restore'].includes(parts[3])) {
          const archived = parts[3] === 'archive';
          store.setArchived(id, archived);
          redirect(response, archived ? '/' : '/?filter=Archived');
        } else if (request.method === 'POST' && parts[3] === 'default-task-priority') {
          const form = await readForm(request);
          const result = store.setDefaultTaskPriority(id, form.get('priority'));
          if (result.error) {
            send(response, result.status, result.error, 'text/plain; charset=utf-8');
          } else {
            redirect(response, projectLocation(id, taskFilter(form.get('filter')), taskPriorityFilter(form.get('priorityFilter'))));
          }
        } else if (request.method === 'POST' && parts[3] === 'rename') {
          const form = await readForm(request);
          const filter = taskFilter(form.get('filter'));
          const priorityFilter = taskPriorityFilter(form.get('priorityFilter'));
          const name = form.get('name') ?? '';
          const result = store.rename(id, name);
          if (result.error) {
            send(response, result.status, projectPage(project, store.tasks.list(id, filter, priorityFilter), {
              filter, priorityFilter, renameState: { error: result.error, submittedName: name },
            }));
          } else {
            redirect(response, projectLocation(id, filter, priorityFilter));
          }
        } else if (request.method === 'POST' && parts[3] === 'tasks') {
          if (project.archived) {
            send(response, 409, 'Archived project cannot be changed', 'text/plain; charset=utf-8');
            return;
          }
          const form = await readForm(request);
          const filter = taskFilter(form.get('filter'));
          const priorityFilter = taskPriorityFilter(form.get('priorityFilter'));
          if (parts.length === 4) {
            const title = form.get('title') ?? '';
            const task = store.tasks.create(id, title);
            if (task.error) {
              send(response, 400, projectPage(project, store.tasks.list(id, filter, priorityFilter), {
                filter, priorityFilter, error: task.error, submittedTitle: title,
              }));
              return;
            }
          } else {
            const taskId = Number(parts[4]);
            if (!Number.isSafeInteger(taskId)) {
              send(response, 404, notFoundPage());
              return;
            }
            if (parts[5] === 'rename') {
              const title = form.get('title') ?? '';
              const result = store.tasks.rename(id, taskId, title);
              if (result.error) {
                send(response, result.status, result.status === 404 ? notFoundPage() :
                  projectPage(project, store.tasks.list(id, filter, priorityFilter), {
                    filter, priorityFilter,
                    taskRenameState: { taskId, error: result.error, submittedTitle: title },
                  }));
                return;
              }
            } else if (parts[5] === 'due-date') {
              const result = store.tasks.setDueDate(id, taskId, form.get('dueDate') ?? '');
              if (result.error) {
                send(response, result.status, result.status === 404 ? notFoundPage() :
                  projectPage(project, store.tasks.list(id, filter, priorityFilter), {
                    filter, priorityFilter, taskDueDateState: { taskId, error: result.error },
                  }));
                return;
              }
            } else if (parts[5] === 'priority') {
              const result = store.tasks.setPriority(id, taskId, form.get('priority'));
              if (result.error) {
                if (result.status === 404) {
                  send(response, 404, notFoundPage());
                } else {
                  send(response, result.status, result.error, 'text/plain; charset=utf-8');
                }
                return;
              }
            } else if (!store.tasks.setCompleted(id, taskId, form.get('completed') === 'on')) {
              send(response, 404, notFoundPage());
              return;
            }
          }
          redirect(response, projectLocation(id, filter, priorityFilter));
        } else {
          send(response, 404, notFoundPage());
        }
      } else {
        send(response, 404, notFoundPage());
      }
    } catch (error) {
      if (!error.status) console.error(error);
      if (!response.headersSent) {
        send(response, error.status ?? 500, error.status ? error.message : 'Unable to complete request', 'text/plain; charset=utf-8');
      } else {
        response.end();
      }
    }
  });
  server.on('close', () => store.close());
  return server;
}
function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} · Workboard</title>
  <link rel="stylesheet" href="/styles.css">
  <script src="/app.js" defer></script>
</head>
<body><main>${content}</main></body>
</html>`;
}

export function projectsPage(projects, error = '', submittedName = '', filter = 'Active') {
  return page('Projects', `
    <p class="eyebrow">YOUR WORK, ORGANIZED</p>
    <h1>Workboard</h1>
    <form class="create-form" action="/projects" method="post">
      <label for="project-name">Project name</label>
      <div class="form-controls">
        <input id="project-name" name="name" type="text" value="${escapeHtml(submittedName)}">
        <button type="submit">Create project</button>
      </div>
      ${error ? `<p class="alert" role="alert">${escapeHtml(error)}</p>` : ''}
    </form>
    <form class="project-filter" action="/" method="get">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" data-submit-on-change>
        ${['Active', 'Archived'].map((option) => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
      <noscript><button type="submit">Apply filter</button></noscript>
    </form>
    <section aria-label="Projects" class="project-list">
      ${projects.length ? projects.map((project) => `
        <article class="project-row" data-testid="project-row">
          <span class="project-name">${escapeHtml(project.name)}</span>
          <span data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span>
          <div class="project-actions">
            <form action="/projects/${project.id}" method="get">
              <button class="secondary" type="submit">Open project</button>
            </form>
            <form action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}" method="post">
              <button class="secondary" type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
            </form>
          </div>
        </article>`).join('') : `<p class="empty">${filter === 'Archived' ? 'No archived projects.' : 'No projects yet. Create a project to get started.'}</p>`}
    </section>`);
}

export function projectPage(project, tasks = [], {
  filter = 'All', priorityFilter = 'All', error = '', submittedTitle = '',
  renameState = {}, taskRenameState = {}, taskDueDateState = {},
} = {}) {
  return page(project.name, `
    <form action="/" method="get"><button class="secondary" type="submit">Projects</button></form>
    <p class="eyebrow detail-label">PROJECT</p>
    <h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form class="create-form rename-form" action="/projects/${project.id}/rename" method="post">
      <input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">
      <label for="new-project-name">New project name</label>
      <div class="form-controls">
        <input id="new-project-name" name="name" type="text" value="${escapeHtml(renameState.submittedName ?? project.name)}"${project.archived ? ' disabled' : ''}>
        <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button>
      </div>
      ${renameState.error ? `<p class="alert" role="alert">${escapeHtml(renameState.error)}</p>` : ''}
    </form>
    <form class="create-form" action="/projects/${project.id}/default-task-priority" method="post">
      <input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">
      <label for="default-task-priority">Default task priority</label>
      <select id="default-task-priority" name="priority"${project.archived ? ' disabled' : ''} data-submit-on-change>
        ${['Low', 'Normal', 'High'].map((priority) => `<option${project.default_task_priority === priority ? ' selected' : ''}>${priority}</option>`).join('')}
      </select>
      <noscript><button type="submit"${project.archived ? ' disabled' : ''}>Save default priority</button></noscript>
    </form>
    <form class="create-form" action="/projects/${project.id}/tasks" method="post">
      <input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">
      <label for="task-title">Task title</label>
      <div class="form-controls">
        <input id="task-title" name="title" type="text" value="${escapeHtml(submittedTitle)}">
        <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button>
      </div>
      ${error ? `<p class="alert" role="alert">${escapeHtml(error)}</p>` : ''}
    </form>
    <form class="task-filter" action="/projects/${project.id}" method="get">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" data-submit-on-change>
        ${['All', 'Open', 'Completed'].map((option) => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
      <label for="priority-filter">Priority filter</label>
      <select id="priority-filter" name="priorityFilter" data-submit-on-change>
        ${['All', 'Low', 'Normal', 'High'].map((option) => `<option${priorityFilter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
      <noscript><button type="submit">Apply filter</button></noscript>
    </form>
    <section aria-label="Tasks">
      ${tasks.length ? tasks.map((task) => `
        <article class="task-row" data-testid="task-row">
          <span class="task-title">${escapeHtml(task.title)}</span>
          <form action="/projects/${project.id}/tasks/${task.id}/completion" method="post">
            <input type="hidden" name="filter" value="${filter}">
            <input type="hidden" name="priorityFilter" value="${priorityFilter}">
            <input type="checkbox" name="completed" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''} data-submit-on-change>
            <noscript><button type="submit"${project.archived ? ' disabled' : ''}>Save completion</button></noscript>
          </form>
          <form action="/projects/${project.id}/tasks/${task.id}/priority" method="post">
            <input type="hidden" name="filter" value="${filter}">
            <input type="hidden" name="priorityFilter" value="${priorityFilter}">
            <label for="task-priority-${task.id}">Task priority</label>
            <select id="task-priority-${task.id}" name="priority"${project.archived ? ' disabled' : ''} data-submit-on-change>
              ${['Low', 'Normal', 'High'].map((priority) => `<option${task.priority === priority ? ' selected' : ''}>${priority}</option>`).join('')}
            </select>
            <noscript><button type="submit"${project.archived ? ' disabled' : ''}>Save priority</button></noscript>
          </form>
          <form class="task-rename-form" action="/projects/${project.id}/tasks/${task.id}/rename" method="post">
            <input type="hidden" name="filter" value="${filter}">
            <input type="hidden" name="priorityFilter" value="${priorityFilter}">
            <label for="new-task-title-${task.id}">New task title</label>
            <div class="form-controls">
              <input id="new-task-title-${task.id}" name="title" type="text" value="${escapeHtml(taskRenameState.taskId === task.id ? taskRenameState.submittedTitle : task.title)}"${project.archived ? ' disabled' : ''}>
              <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button>
            </div>
            ${taskRenameState.taskId === task.id && taskRenameState.error ? `<p class="alert" role="alert">${escapeHtml(taskRenameState.error)}</p>` : ''}
          </form>
          <form class="task-due-date-form" action="/projects/${project.id}/tasks/${task.id}/due-date" method="post">
            <input type="hidden" name="filter" value="${filter}">
            <input type="hidden" name="priorityFilter" value="${priorityFilter}">
            <label for="task-due-date-${task.id}">Task due date</label>
            <div class="form-controls">
              <input id="task-due-date-${task.id}" name="dueDate" type="text" value="${escapeHtml(task.due_date ?? '')}"${project.archived ? ' disabled' : ''}>
              <button type="submit"${project.archived ? ' disabled' : ''}>Save due date</button>
            </div>
            ${taskDueDateState.taskId === task.id && taskDueDateState.error ? `<p class="alert" role="alert">${escapeHtml(taskDueDateState.error)}</p>` : ''}
          </form>
        </article>`).join('') : '<p class="empty">No tasks to show.</p>'}
    </section>`);
}

export function notFoundPage() {
  return page('Page not found', '<h1>Page not found</h1><form action="/" method="get"><button type="submit">Projects</button></form>');
}
document.addEventListener('change', (event) => {
  if (event.target.matches('[data-submit-on-change]')) {
    event.target.form.requestSubmit();
  }
});

// Calendar days are validated arithmetically, without timezone conversion.
// null clears a date; undefined signals invalid input.
export function normalizeDueDate(value) {
  const date = value.trim();
  if (!date) return null;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return undefined;
  const [year, month, day] = date.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return undefined;
  const leapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [31, leapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= daysInMonth[month - 1] ? date : undefined;
}
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { normalizeDueDate } from './due-date.js';

export function openWorkboardStore(databasePath) {
  mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec('PRAGMA foreign_keys = ON');
  database.exec(`
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK(length(trim(name)) > 0),
      archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1)),
      default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK(default_task_priority IN ('Low', 'Normal', 'High'))
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK(length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1)),
      priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High')),
      due_date TEXT DEFAULT NULL
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1))');
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
    database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))");
  }
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_task_priority')) {
    database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK(default_task_priority IN ('Low', 'Normal', 'High'))");
  }
  if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
    database.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT DEFAULT NULL');
  }
  const list = database.prepare(`
    SELECT projects.id, projects.name, projects.archived,
      COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
    FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
    WHERE projects.archived = ?
    GROUP BY projects.id ORDER BY projects.id
  `);
  const find = database.prepare('SELECT id, name, archived, default_task_priority FROM projects WHERE id = ?');
  const setArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const rename = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
  const setDefaultTaskPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ? AND archived = 0');
  const listTasks = database.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY id');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title, priority) VALUES (?, ?, ?)');
  const findTask = database.prepare('SELECT id FROM tasks WHERE id = ? AND project_id = ?');
  const renameTask = database.prepare(`
    UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const updateTask = database.prepare(`
    UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const setTaskPriority = database.prepare(`
    UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);
  const setTaskDueDate = database.prepare(`
    UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?
      AND EXISTS (SELECT 1 FROM projects WHERE id = tasks.project_id AND archived = 0)
  `);

  return {
    list: (filter = 'Active') => list.all(filter === 'Archived' ? 1 : 0),
    find: (id) => find.get(id),
    setArchived: (id, archived) => setArchived.run(archived ? 1 : 0, id).changes > 0,
    create(name) {
      const trimmedName = name.trim();
      if (!trimmedName) return { error: 'Project name is required' };
      const result = insert.run(trimmedName);
      return { id: Number(result.lastInsertRowid), name: trimmedName };
    },
    rename(id, name) {
      const project = find.get(id);
      if (!project) return { error: 'Project not found', status: 404 };
      if (project.archived) return { error: 'Archived project cannot be changed', status: 409 };
      const trimmedName = name.trim();
      if (!trimmedName) return { error: 'Project name is required', status: 400 };
      rename.run(trimmedName, id);
      return { id, name: trimmedName };
    },
    setDefaultTaskPriority(id, priority) {
      const project = find.get(id);
      if (!project) return { error: 'Project not found', status: 404 };
      if (project.archived) return { error: 'Archived project cannot be changed', status: 409 };
      if (!['Low', 'Normal', 'High'].includes(priority)) {
        return { error: 'Invalid task priority', status: 400 };
      }
      setDefaultTaskPriority.run(priority, id);
      return { id, default_task_priority: priority };
    },
    tasks: {
      list(projectId, filter = 'All', priorityFilter = 'All') {
        return listTasks.all(projectId).filter((task) =>
          (filter === 'All' || Boolean(task.completed) === (filter === 'Completed')) &&
          (priorityFilter === 'All' || task.priority === priorityFilter));
      },
      create(projectId, title) {
        const project = find.get(projectId);
        if (!project) return { error: 'Project not found' };
        if (project.archived) return { error: 'Archived project cannot be changed' };
        const trimmedTitle = title.trim();
        if (!trimmedTitle) return { error: 'Task title is required' };
        const result = insertTask.run(projectId, trimmedTitle, project.default_task_priority);
        return { id: Number(result.lastInsertRowid), title: trimmedTitle, completed: 0, priority: project.default_task_priority, due_date: null };
      },
      rename(projectId, taskId, title) {
        const project = find.get(projectId);
        if (!project || !findTask.get(taskId, projectId)) {
          return { error: 'Task not found', status: 404 };
        }
        if (project.archived) return { error: 'Archived project cannot be changed', status: 409 };
        const trimmedTitle = title.trim();
        if (!trimmedTitle) return { error: 'Task title is required', status: 400 };
        renameTask.run(trimmedTitle, taskId, projectId);
        return { id: taskId, title: trimmedTitle };
      },
      setCompleted(projectId, taskId, completed) {
        return updateTask.run(completed ? 1 : 0, taskId, projectId).changes > 0;
      },
      setPriority(projectId, taskId, priority) {
        const project = find.get(projectId);
        if (!project || !findTask.get(taskId, projectId)) {
          return { error: 'Task not found', status: 404 };
        }
        if (project.archived) return { error: 'Archived project cannot be changed', status: 409 };
        if (!['Low', 'Normal', 'High'].includes(priority)) {
          return { error: 'Invalid task priority', status: 400 };
        }
        setTaskPriority.run(priority, taskId, projectId);
        return { id: taskId, priority };
      },
      setDueDate(projectId, taskId, value) {
        const project = find.get(projectId);
        if (!project || !findTask.get(taskId, projectId)) {
          return { error: 'Task not found', status: 404 };
        }
        if (project.archived) return { error: 'Archived project cannot be changed', status: 409 };
        const dueDate = normalizeDueDate(value);
        if (dueDate === undefined) {
          return { error: 'Due date must be a valid YYYY-MM-DD date', status: 400 };
        }
        setTaskDueDate.run(dueDate, taskId, projectId);
        return { id: taskId, due_date: dueDate };
      },
    },
    close: () => database.close(),
  };
}
