    await post('/projects/1/restore');
    assert.equal(await get(path), filtered);
    assert.equal(await get('/projects/1'), saved);
    assert.match(saved, /id=\"due-from\" name=\"rangeFrom\" type=\"text\" value=\"\"/);
    assert.match(saved, /id=\"due-through\" name=\"rangeThrough\" type=\"text\" value=\"\"/);
  } finally {
    await running?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});
EOF
cat >> README.md <<'EOF'

Project pages have Due from and Due through textboxes and Apply due range.
Boundaries use the same Gregorian date validation as task dates, are trimmed,
and match inclusively. Either boundary can be blank; with both blank, undated
tasks also match. The applied range intersects completion and priority filters
without changing saved tasks or all-task summaries. Invalid ranges show an alert
and preserve the previously applied range. Edits retain all selected filters and
immediately update matching rows. Range controls remain usable when archived.
The applied range is carried in the page URL and forms, not stored in SQLite;
opening a project from the list starts with empty boundaries.
EOF"

/bin/bash -lc 'git diff --check
for source in server.js src/*.js public/*.js test/*.js; do node --check "$source" || exit 1; done
node --input-type=module <<'"'JS'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'workboard.sqlite') },
  stdio: ['ignore', 'pipe', 'pipe'], detached: true,
});
try {
  let output = '';
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Launch timed out')), 5000);
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/Workboard listening on 0\\.0\\.0\\.0:(\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
    child.once('error', error => { clearTimeout(timer); reject(error); });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start binds to 0.0.0.0; /health returns 200 and expected JSON');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
JS"

